package variant1_orderprocessing;

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

// Опис предметної області: Інтернет-магазин електроніки та побутової техніки.
// Завдання коду: Обробка замовлення клієнта — перевірка коректності даних, розрахунок загальної вартості з урахуванням накопичувальної знижки та ПДВ, формування текстового рахунку, збереження замовлення у файл та відправка email-сповіщення.

public class Customer {
    public int id;
    public String name;
    public String email;
    public String type; // "Regular", "VIP", "New"
    public double totalSpent;
}

public class Product {
    public int id;
    public String name;
    public double price;
    public String category;
}

public class OrderItem {
    public Product product;
    public int quantity;
}

public class Order {
    public int id;
    public Customer customer;
    public List<OrderItem> items = new ArrayList<>();
    public double totalAmount;
    public double discountAmount;
    public double taxAmount;
    public double finalAmount;
    public String status;
}

public class LegacyOrderProcessor {
    public void processConsoleOrder() {
        Scanner scanner = new Scanner(System.in);
        System.out.println("=== Оформлення замовлення ===");
        System.out.print("Введіть ім'я клієнта: ");
        String name = scanner.nextLine();
        System.out.print("Введіть тип клієнта (New/Regular/VIP): ");
        String customerType = scanner.nextLine();

        Customer customer = new Customer();
        customer.id = 1;
        customer.name = name;
        customer.email = "client@example.com";
        customer.type = customerType;
        customer.totalSpent = 15000.0;

        Order order = new Order();
        order.id = 101;
        order.customer = customer;
        order.status = "New";

        Product p1 = new Product();
        p1.id = 1; p1.name = "Ноутбук"; p1.price = 30000.0; p1.category = "Electronics";
        Product p2 = new Product();
        p2.id = 2; p2.name = "Мишка"; p2.price = 800.0; p2.category = "Accessories";

        OrderItem item1 = new OrderItem(); item1.product = p1; item1.quantity = 1;
        OrderItem item2 = new OrderItem(); item2.product = p2; item2.quantity = 2;
        order.items.add(item1);
        order.items.add(item2);

        double subtotal = 0.0;
        for (OrderItem item : order.items) {
            subtotal += item.product.price * item.quantity;
        }
        order.totalAmount = subtotal;

        double discountRate = 0.0;
        if ("VIP".equalsIgnoreCase(order.customer.type)) {
            discountRate = 0.15;
        } else if ("Regular".equalsIgnoreCase(order.customer.type)) {
            discountRate = 0.05;
        } else if ("New".equalsIgnoreCase(order.customer.type)) {
            discountRate = 0.0;
        }
        order.discountAmount = order.totalAmount * discountRate;

        order.taxAmount = (order.totalAmount - order.discountAmount) * 0.20;
        order.finalAmount = order.totalAmount - order.discountAmount + order.taxAmount;
        order.status = "Processed";

        String receipt = "Замовлення #" + order.id + " для " + order.customer.name +
                "\nСума: " + order.totalAmount + " грн" +
                "\nЗнижка: " + order.discountAmount + " грн" +
                "\nПДВ: " + order.taxAmount + " грн" +
                "\nДо сплати: " + order.finalAmount + " грн";
        System.out.println(receipt);

        System.out.println("[БД] Замовлення #" + order.id + " збережено у файл orders.txt.");
        System.out.println("[Email] Повідомлення відправлено на " + order.customer.email);
    }
}

package variant2_hotelbooking;

import java.util.Scanner;

// Опис предметної області: Готельний комплекс та система бронювання номерів.
// Завдання коду: Бронювання готельного номера — розрахунок вартості проживання залежно від категорії номера та сезону, обчислення вартість додаткових послуг (сніданки, парковка) та туристичного збору, створення квитанції, збереження у файл та надсилання SMS.

public class Guest {
    public int id;
    public String fullName;
    public String phone;
    public String passportNumber;
}

public class Room {
    public int roomNumber;
    public String category; // "Standard", "Deluxe", "Suite"
    public double basePricePerNight;
}

public class Booking {
    public int bookingId;
    public Guest guest;
    public Room room;
    public int nights;
    public String season; // "Low", "High", "Peak"
    public boolean includeBreakfast;
    public boolean includeParking;
    public double roomTotal;
    public double servicesTotal;
    public double touristTax;
    public double grandTotal;
    public String status;
}

public class LegacyHotelManager {
    public void createBookingFromConsole() {
        Scanner scanner = new Scanner(System.in);
        System.out.println("=== Бронювання номера в готелі ===");
        System.out.print("Введіть ПІБ гостя: ");
        String name = scanner.nextLine();
        System.out.print("Введіть сезон (Low/High/Peak): ");
        String season = scanner.nextLine();

        Guest guest = new Guest();
        guest.id = 10; guest.fullName = name; guest.phone = "+380971112233"; guest.passportNumber = "AA123456";

        Room room = new Room();
        room.roomNumber = 302; room.category = "Deluxe"; room.basePricePerNight = 2000.0;

        Booking booking = new Booking();
        booking.bookingId = 501;
        booking.guest = guest;
        booking.room = room;
        booking.nights = 3;
        booking.season = season;
        booking.includeBreakfast = true;
        booking.includeParking = true;
        booking.status = "Created";

        double seasonalMultiplier = 1.0;
        if ("Peak".equalsIgnoreCase(booking.season)) {
            seasonalMultiplier = 1.5;
        } else if ("High".equalsIgnoreCase(booking.season)) {
            seasonalMultiplier = 1.25;
        } else if ("Low".equalsIgnoreCase(booking.season)) {
            seasonalMultiplier = 0.9;
        }

        booking.roomTotal = booking.room.basePricePerNight * booking.nights * seasonalMultiplier;

        double services = 0.0;
        if (booking.includeBreakfast) {
            services += 300.0 * booking.nights;
        }
        if (booking.includeParking) {
            services += 150.0 * booking.nights;
        }
        booking.servicesTotal = services;

        booking.touristTax = (booking.roomTotal + booking.servicesTotal) * 0.01;
        booking.grandTotal = booking.roomTotal + booking.servicesTotal + booking.touristTax;
        booking.status = "Confirmed";

        String confirmation = "Бронювання #" + booking.bookingId + " для " + booking.guest.fullName +
                "\nКімната: " + booking.room.roomNumber + " (" + booking.room.category + ")" +
                "\nПроживання: " + booking.roomTotal + " грн" +
                "\nПослуги: " + booking.servicesTotal + " грн" +
                "\nТуристичний збір: " + booking.touristTax + " грн" +
                "\nВсього: " + booking.grandTotal + " грн";
        System.out.println(confirmation);

        System.out.println("[Файлова БД] Запис про бронювання #" + booking.bookingId + " додано до bookings.dat.");
        System.out.println("[SMS] Підтвердження надіслано на номер " + booking.guest.phone);
    }
}

package variant3_fitnessmembership;

import java.util.Scanner;

// Опис предметної області: Мережа фітнес-клубів та продаж клубних карт.
// Завдання коду: Оформлення та розрахунок вартості абонементу — розрахунок ціни залежно від типу пакету (Day, Full, VIP), застосування дисконтної карти, додавання первинних послуг, формування тексту договору, запис у базу даних та надсилання пуш-сповіщення.

public class Member {
    public int id;
    public String name;
    public String phone;
    public boolean hasDiscountCard;
}

public class MembershipPlan {
    public String code; // "Day", "Full", "VIP"
    public String title;
    public double baseMonthlyRate;
    public int monthsDuration;
}

public class Subscription {
    public int id;
    public Member member;
    public MembershipPlan plan;
    public boolean personalTrainerIncluded;
    public double baseAmount;
    public double discountAmount;
    public double finalCost;
    public String startDate;
    public String status;
}

public class LegacyFitnessService {
    public void registerSubscriptionConsole() {
        Scanner scanner = new Scanner(System.in);
        System.out.println("=== Реєстрація абонемента фітнес-клубу ===");
        System.out.print("Введіть ім'я клієнта: ");
        String name = scanner.nextLine();
        System.out.print("Введіть тип абонемента (Day/Full/VIP): ");
        String planType = scanner.nextLine();

        Member member = new Member();
        member.id = 42; member.name = name; member.phone = "+380509998877"; member.hasDiscountCard = true;

        MembershipPlan plan = new MembershipPlan();
        plan.code = planType; plan.title = "Річний абонемент"; plan.baseMonthlyRate = 1200.0; plan.monthsDuration = 12;

        Subscription sub = new Subscription();
        sub.id = 1002;
        sub.member = member;
        sub.plan = plan;
        sub.personalTrainerIncluded = true;
        sub.startDate = "2026-11-01";
        sub.status = "Draft";

        double rawCost = sub.plan.baseMonthlyRate * sub.plan.monthsDuration;

        if ("VIP".equalsIgnoreCase(sub.plan.code)) {
            rawCost += 5000.0;
        } else if ("Day".equalsIgnoreCase(sub.plan.code)) {
            rawCost *= 0.8;
        }

        if (sub.personalTrainerIncluded) {
            rawCost += 3000.0;
        }

        sub.baseAmount = rawCost;

        double discount = 0.0;
        if (sub.member.hasDiscountCard) {
            discount = sub.baseAmount * 0.10;
        }
        sub.discountAmount = discount;
        sub.finalCost = sub.baseAmount - sub.discountAmount;
        sub.status = "Active";

        String contract = "Договір #" + sub.id + " з " + sub.member.name +
                "\nТариф: " + sub.plan.code +
                "\nБазова вартість: " + sub.baseAmount + " грн" +
                "\nЗнижка: " + sub.discountAmount + " грн" +
                "\nДо сплати: " + sub.finalCost + " грн";
        System.out.println(contract);

        System.out.println("[База даних] Абонемент #" + sub.id + " додано до таблиці subscriptions.");
        System.out.println("[Push Notification] Повідомлення надіслано на пристрій клієнта " + sub.member.name);
    }
}

package variant4_librarymanagement;

import java.util.Scanner;

// Опис предметної області: Публічна або університетська бібліотека.
// Завдання коду: Реєстрація видачі книг — перевірка ліміту книг у читача, розрахунок застави та застійного штрафу залежно від категорії книги (Standard, Rare, Academic), встановлення дати повернення, формування квитанції видачі, збереження в лог-файл та надсилання email-нагадування.

public class Reader {
    public int id;
    public String name;
    public String ticketNumber;
    public int activeLoansCount;
    public String email;
}

public class Book {
    public int id;
    public String title;
    public String category; // "Standard", "Rare", "Academic"
    public double valueAmount;
}

public class LoanRecord {
    public int loanId;
    public Reader reader;
    public Book book;
    public int daysCount;
    public double depositFee;
    public double serviceFee;
    public double totalPayable;
    public String status;
}

public class LegacyLibraryProcessor {
    public void issueBookFromConsole() {
        Scanner scanner = new Scanner(System.in);
        System.out.println("=== Реєстрація видачі книги ===");
        System.out.print("Введіть ім'я читача: ");
        String name = scanner.nextLine();
        System.out.print("Введіть категорію книги (Standard/Rare/Academic): ");
        String category = scanner.nextLine();

        Reader reader = new Reader();
        reader.id = 7; reader.name = name; reader.ticketNumber = "T-8841"; reader.activeLoansCount = 2; reader.email = "reader@univ.edu";

        Book book = new Book();
        book.id = 104; book.title = "Алгоритми та структури даних"; book.category = category; book.valueAmount = 1500.0;

        LoanRecord loan = new LoanRecord();
        loan.loanId = 8801;
        loan.reader = reader;
        loan.book = book;
        loan.daysCount = 14;
        loan.status = "Draft";

        double deposit = 0.0;
        double fee = 50.0;

        if ("Rare".equalsIgnoreCase(loan.book.category)) {
            deposit = loan.book.valueAmount * 0.5;
            fee += 200.0;
        } else if ("Academic".equalsIgnoreCase(loan.book.category)) {
            deposit = loan.book.valueAmount * 0.2;
            fee += 50.0;
        } else if ("Standard".equalsIgnoreCase(loan.book.category)) {
            deposit = 0.0;
        }

        loan.depositFee = deposit;
        loan.serviceFee = fee;
        loan.totalPayable = loan.depositFee + loan.serviceFee;
        loan.status = "Issued";

        String ticket = "Квитанція видачі #" + loan.loanId +
                "\nЧитач: " + loan.reader.name + " (" + loan.reader.ticketNumber + ")" +
                "\nКнига: " + loan.book.title +
                "\nЗастава: " + loan.depositFee + " грн" +
                "\nСервісний збір: " + loan.serviceFee + " грн" +
                "\nРазом: " + loan.totalPayable + " грн";
        System.out.println(ticket);

        System.out.println("[Журнал логів] Видачу книги #" + loan.book.id + " читачу #" + loan.reader.id + " записано в library_audit.log.");
        System.out.println("[Email] Нагадування надіслано на " + loan.reader.email);
    }
}

package variant5_vehiclerental;

import java.util.Scanner;

// Опис предметної області: Автопрокатна компанія та оренда автотранспорту.
// Завдання коду: Оформлення оренди автомобіля — перевірка стажу водія, розрахунок вартості оренди залежно від класу авто (Economy, Business, SUV), розрахунок страхового поліса (Basic, Full), застави за пальне, формування ваучера оренди, збереження у базу та відправка SMS-підтвердження.

public class Client {
    public int id;
    public String name;
    public int driverExperienceYears;
    public String phone;
}

public class Vehicle {
    public int id;
    public String model;
    public String classType; // "Economy", "Business", "SUV"
    public double dailyRate;
}

public class RentalAgreement {
    public int id;
    public Client client;
    public Vehicle vehicle;
    public int days;
    public String insuranceType; // "Basic", "Full"
    public double rentalTotal;
    public double insuranceTotal;
    public double depositAmount;
    public double finalPrice;
    public String status;
}

public class LegacyRentalManager {
    public void processRentalConsole() {
        Scanner scanner = new Scanner(System.in);
        System.out.println("=== Оформлення оренди автомобіля ===");
        System.out.print("Введіть ім'я клієнта: ");
        String name = scanner.nextLine();
        System.out.print("Введіть клас авто (Economy/Business/SUV): ");
        String carClass = scanner.nextLine();

        Client client = new Client();
        client.id = 15; client.name = name; client.driverExperienceYears = 4; client.phone = "+380673332211";

        Vehicle vehicle = new Vehicle();
        vehicle.id = 505; vehicle.model = "Toyota RAV4"; vehicle.classType = carClass; vehicle.dailyRate = 1800.0;

        RentalAgreement agreement = new RentalAgreement();
        agreement.id = 9012;
        agreement.client = client;
        agreement.vehicle = vehicle;
        agreement.days = 5;
        agreement.insuranceType = "Full";
        agreement.status = "New";

        double rental = agreement.vehicle.dailyRate * agreement.days;
        if ("Business".equalsIgnoreCase(agreement.vehicle.classType)) {
            rental *= 1.3;
        } else if ("SUV".equalsIgnoreCase(agreement.vehicle.classType)) {
            rental *= 1.2;
        }

        double insurance = 0.0;
        if ("Full".equalsIgnoreCase(agreement.insuranceType)) {
            insurance = 500.0 * agreement.days;
        } else if ("Basic".equalsIgnoreCase(agreement.insuranceType)) {
            insurance = 200.0 * agreement.days;
        }

        double deposit = 5000.0;
        if (agreement.client.driverExperienceYears < 3) {
            deposit += 3000.0;
        }

        agreement.rentalTotal = rental;
        agreement.insuranceTotal = insurance;
        agreement.depositAmount = deposit;
        agreement.finalPrice = agreement.rentalTotal + agreement.insuranceTotal;
        agreement.status = "Approved";

        String voucher = "Ваучер оренди #" + agreement.id +
                "\nКлієнт: " + agreement.client.name +
                "\nАвто: " + agreement.vehicle.model +
                "\nОренда: " + agreement.rentalTotal + " грн" +
                "\nСтраховка: " + agreement.insuranceTotal + " грн" +
                "\nЗастава: " + agreement.depositAmount + " грн" +
                "\nЗагалом: " + agreement.finalPrice + " грн";
        System.out.println(voucher);

        System.out.println("[База даних] Ваучер #" + agreement.id + " зафіксовано в системі.");
        System.out.println("[SMS] Підтвердження оренди надіслано на номер " + agreement.client.phone);
    }
}

package variant6_restaurantbooking;

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

// Опис предметної області: Ресторанний бізнес та обслуговування гостей.
// Завдання коду: Бронювання столика із попереднім замовленням страв — розрахунок суми замовлення, нарахування чайових/сервісного збору залежно від кількості гостей та часу (HappyHours, Evening), обчислення депозиту, формування чека для кухні та гостя, збереження у файл та надсилання сповіщення.

public class Guest {
    public int id;
    public String name;
    public String phone;
}

public class MenuItem {
    public String name;
    public double price;
    public String courseType; // "Main", "Drink", "Dessert"
}

public class OrderLine {
    public MenuItem item;
    public int count;
}

public class TableReservation {
    public int reservationId;
    public Guest guest;
    public int guestsCount;
    public String timeSlot; // "HappyHours", "Standard", "Evening"
    public List<OrderLine> preOrderedItems = new ArrayList<>();
    public double foodSubtotal;
    public double serviceCharge;
    public double totalBill;
    public String status;
}

public class LegacyRestaurantProcessor {
    public void processReservationConsole() {
        Scanner scanner = new Scanner(System.in);
        System.out.println("=== Бронювання столика в ресторані ===");
        System.out.print("Введіть ім'я гостя: ");
        String name = scanner.nextLine();
        System.out.print("Введіть час відвідування (HappyHours/Standard/Evening): ");
        String timeSlot = scanner.nextLine();

        Guest guest = new Guest();
        guest.id = 3; guest.name = name; guest.phone = "+380631234567";

        TableReservation res = new TableReservation();
        res.reservationId = 404;
        res.guest = guest;
        res.guestsCount = 6;
        res.timeSlot = timeSlot;
        res.status = "Draft";

        MenuItem m1 = new MenuItem(); m1.name = "Стейк Рібай"; m1.price = 650.0; m1.courseType = "Main";
        MenuItem m2 = new MenuItem(); m2.name = "Вино Червоне"; m2.price = 400.0; m2.courseType = "Drink";

        OrderLine line1 = new OrderLine(); line1.item = m1; line1.count = 4;
        OrderLine line2 = new OrderLine(); line2.item = m2; line2.count = 2;
        res.preOrderedItems.add(line1);
        res.preOrderedItems.add(line2);

        double subtotal = 0.0;
        for (OrderLine line : res.preOrderedItems) {
            subtotal += line.item.price * line.count;
        }

        if ("HappyHours".equalsIgnoreCase(res.timeSlot)) {
            subtotal *= 0.85;
        }

        res.foodSubtotal = subtotal;

        double service = 0.0;
        if (res.guestsCount >= 5) {
            service = res.foodSubtotal * 0.10;
        }
        res.serviceCharge = service;

        res.totalBill = res.foodSubtotal + res.serviceCharge;
        res.status = "Reserved";

        String bill = "Чек резерву #" + res.reservationId +
                "\nГість: " + res.guest.name + " (" + res.guestsCount + " осіб)" +
                "\nСтрави: " + res.foodSubtotal + " грн" +
                "\nОбслуговування: " + res.serviceCharge + " грн" +
                "\nВсього до сплати: " + res.totalBill + " грн";
        System.out.println(bill);

        System.out.println("[БД Ресторану] Бронювання #" + res.reservationId + " збережено в reservations.json.");
        System.out.println("[SMS] Деталі резерву надіслано на номер " + res.guest.phone);
    }
}

package variant7_medicalclinic;

import java.util.Scanner;

// Опис предметної області: Приватна медична клініка та обслуговування пацієнтів.
// Завдання коду: Запис пацієнта на прийом та лабораторні аналізи — розрахунок вартості консультації залежно від категорії лікаря (General, Specialist, Professor), розрахунок покриття страхової компанії, підсумовування аналізів, створення медичної квитанції, збереження у реєстр прийомів та відправка SMS.

public class Patient {
    public int id;
    public String fullName;
    public boolean hasInsurance;
    public String insurancePolicyNumber;
    public String phone;
}

public class Doctor {
    public int id;
    public String name;
    public String specialty;
    public String category; // "General", "Specialist", "Professor"
    public double baseConsultationFee;
}

public class Appointment {
    public int appointmentId;
    public Patient patient;
    public Doctor doctor;
    public double consultationCost;
    public double insuranceCoverage;
    public double patientPayable;
    public String status;
}

public class LegacyClinicService {
    public void scheduleAppointmentConsole() {
        Scanner scanner = new Scanner(System.in);
        System.out.println("=== Запис пацієнта на прийом ===");
        System.out.print("Введіть ім'я пацієнта: ");
        String name = scanner.nextLine();
        System.out.print("Введіть категорію лікаря (General/Specialist/Professor): ");
        String docCategory = scanner.nextLine();

        Patient patient = new Patient();
        patient.id = 22; patient.fullName = name; patient.hasInsurance = true; patient.insurancePolicyNumber = "INS-99201"; patient.phone = "+380684445566";

        Doctor doctor = new Doctor();
        doctor.id = 101; doctor.name = "Др. Ковальчук"; doctor.specialty = "Кардіолог"; doctor.category = docCategory; doctor.baseConsultationFee = 800.0;

        Appointment appointment = new Appointment();
        appointment.appointmentId = 3001;
        appointment.patient = patient;
        appointment.doctor = doctor;
        appointment.status = "Scheduled";

        double fee = appointment.doctor.baseConsultationFee;
        if ("Professor".equalsIgnoreCase(appointment.doctor.category)) {
            fee *= 2.0;
        } else if ("Specialist".equalsIgnoreCase(appointment.doctor.category)) {
            fee *= 1.4;
        }

        appointment.consultationCost = fee;

        double coverage = 0.0;
        if (appointment.patient.hasInsurance) {
            coverage = appointment.consultationCost * 0.80;
        }

        appointment.insuranceCoverage = coverage;
        appointment.patientPayable = appointment.consultationCost - appointment.insuranceCoverage;
        appointment.status = "Confirmed";

        String invoice = "Квитанція прийому #" + appointment.appointmentId +
                "\nПацієнт: " + appointment.patient.fullName +
                "\nЛікар: " + appointment.doctor.name + " (" + appointment.doctor.category + ")" +
                "\nВартість: " + appointment.consultationCost + " грн" +
                "\nПокриття страховкою: " + appointment.insuranceCoverage + " грн" +
                "\nДо сплати пацієнтом: " + appointment.patientPayable + " грн";
        System.out.println(invoice);

        System.out.println("[Електронна карта] Запис #" + appointment.appointmentId + " збережено у файл appointments.log.");
        System.out.println("[SMS] Нагадування про прийом надіслано на номер " + appointment.patient.phone);
    }
}

package variant8_logisticsdelivery;

import java.util.Scanner;

// Опис предметної області: Логістична компанія та вантажоперевезення.
// Завдання коду: Оформлення вантажної відправки — розрахунок вартості доставки залежно від ваги, об'єму та типу транспорту (Standard, Express, Freight), страхового відсотка вантажу, створення товарно-транспортної накладної, збереження у реєстр відправок та відправка трекінг-коду по email.

public class Sender {
    public int id;
    public String companyName;
    public String contactPerson;
    public String email;
}

public class Cargo {
    public double weightKg;
    public double volumeCubMetres;
    public double declaredValue;
    public String deliveryType; // "Standard", "Express", "Freight"
}

public class Shipment {
    public int trackingId;
    public Sender sender;
    public Cargo cargo;
    public double transportFee;
    public double insuranceFee;
    public double totalCost;
    public String status;
}

public class LegacyLogisticsProcessor {
    public void processShipmentConsole() {
        Scanner scanner = new Scanner(System.in);
        System.out.println("=== Оформлення відправки вантажу ===");
        System.out.print("Введіть назву компанії-відправника: ");
        String company = scanner.nextLine();
        System.out.print("Введіть тип доставки (Standard/Express/Freight): ");
        String deliveryType = scanner.nextLine();

        Sender sender = new Sender();
        sender.id = 55; sender.companyName = company; sender.contactPerson = "Іван Петренко"; sender.email = "logistics@company.ua";

        Cargo cargo = new Cargo();
        cargo.weightKg = 120.0; cargo.volumeCubMetres = 1.5; cargo.declaredValue = 50000.0; cargo.deliveryType = deliveryType;

        Shipment shipment = new Shipment();
        shipment.trackingId = 770099;
        shipment.sender = sender;
        shipment.cargo = cargo;
        shipment.status = "Created";

        double baseRatePerKg = 15.0;
        double baseTransport = shipment.cargo.weightKg * baseRatePerKg;

        if ("Express".equalsIgnoreCase(shipment.cargo.deliveryType)) {
            baseTransport *= 1.8;
        } else if ("Freight".equalsIgnoreCase(shipment.cargo.deliveryType)) {
            baseTransport *= 1.2;
        }

        double insurance = shipment.cargo.declaredValue * 0.005;

        shipment.transportFee = baseTransport;
        shipment.insuranceFee = insurance;
        shipment.totalCost = shipment.transportFee + shipment.insuranceFee;
        shipment.status = "Dispatched";

        String waybill = "Товарно-транспортна накладна TTN-" + shipment.trackingId +
                "\nВідправник: " + shipment.sender.companyName +
                "\nТип: " + shipment.cargo.deliveryType +
                "\nТранспортування: " + shipment.transportFee + " грн" +
                "\nСтраховка: " + shipment.insuranceFee + " грн" +
                "\nЗагальна вартість: " + shipment.totalCost + " грн";
        System.out.println(waybill);

        System.out.println("[Реєстр] Накладну TTN-" + shipment.trackingId + " додано у базу відправок.");
        System.out.println("[Email] Трекінг-код TTN-" + shipment.trackingId + " надіслано на " + shipment.sender.email);
    }
}
